-- Fund return and risk metrics; output generated by Python.
SELECT fund_name, cagr, annualized_volatility, sharpe_ratio, sortino_ratio, max_drawdown
FROM fund_metrics
ORDER BY sharpe_ratio DESC;

-- Funds that underperformed their mapped benchmark over the common observation window.
SELECT fund_name, benchmark_name, fund_total_return, benchmark_total_return, active_return_pp
FROM benchmark_comparison
WHERE active_return_pp < 0
ORDER BY active_return_pp ASC;

-- Compare historical CAPM estimates while retaining sample sizes.
SELECT fund_name, beta, alpha_annualized, r_squared, n_obs, alpha_pvalue, beta_pvalue
FROM capm_regression
ORDER BY beta DESC;

-- Allocation weights from the constrained maximum-Sharpe optimizer.
SELECT fund_name, weight
FROM portfolio_weights
ORDER BY weight DESC;
